{
  "headline": "Hydrochlorothiazide is not on FDA's shortage list as of 2026-10-21; current inventory covers about 19 days at both sites",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include hydrochlorothiazide as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East has 231 tablets of the 25 mg presentation on hand, which at 11.6 tablets per day provides 19.9 days of supply.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 262 tablets of the same strength, yielding 19 days of supply at 13.8 tablets per day.",
      "cites": ["D2"]
    },
    {
      "text": "The top-ranked purchasing option is to buy from Accord Healthcare Inc., which is also not on FDA's shortage list today.",
      "cites": ["D4"]
    },
    {
      "text": "Secondary options include Actavis Pharma, Inc. and Aurobindo Pharma Limited, neither of which appears on the current shortage list.",
      "cites": ["D5", "D6"]
    },
    {
      "text": "A prior FDA posting shows Teva Pharmaceuticals USA, Inc. discontinued its hydrochlorothiazide capsule on 2025-11-19, but that product is a capsule rather than the tablet strength in use.",
      "cites": ["E10"]
    }
  ]
}
